package vn.aicrm.crm;

import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import org.springframework.http.HttpStatus;
import vn.aicrm.shared.*;
import static vn.aicrm.shared.RetailAccess.*;

@Service
public class CrmPipeline {
 private final RetailAccess r;
 private final PartnersPort partners;
 public CrmPipeline(RetailAccess r,PartnersPort partners){this.r=r;this.partners=partners;}
 private String feature(boolean opp){return opp?"opportunities":"leads";}
 private String table(boolean opp){return opp?"crm_opportunity":"crm_lead";}
 private String bounded(JsonNode x,String key,int max){String v=text(x,key,"");if(v.length()>max)throw problem("INVALID_FIELD","Trường "+key+" tối đa "+max+" ký tự");return v;}
 private void version(Map<String,Object> row,JsonNode x){if(!x.path("version").isIntegralNumber()||x.path("version").asInt(-1)!=((Number)row.get("version")).intValue())throw problem("VERSION_CONFLICT","Hồ sơ đã thay đổi, tải lại trước khi lưu",HttpStatus.CONFLICT);}
 private UUID owner(Authentication a,JsonNode x){UUID id=optional(x,"ownerId");if(id==null)id=r.actor(a);if(r.db.queryForObject("select count(*) from identity.account where tenant_id=? and id=? and enabled",Integer.class,r.tenant(a),id)==0)throw problem("INVALID_OWNER","Người phụ trách không hợp lệ");return id;}
 private UUID branch(Authentication a,JsonNode x){UUID id=uuid(x,"branchId");r.branch(a,id);if(r.db.queryForObject("select count(*) from retail.branch where tenant_id=? and id=? and active",Integer.class,r.tenant(a),id)==0)throw problem("INVALID_BRANCH","Địa điểm không hoạt động");return id;}
 private Map<String,Object> scoped(Authentication a,boolean opp,UUID id){var row=r.one(table(opp),r.tenant(a),id);r.branch(a,(UUID)row.get("branch_id"));return row;}
 private void customer(Authentication a,UUID id){r.gate(a,"customer","VIEW");var row=r.one("partner",r.tenant(a),id);if(!Boolean.TRUE.equals(row.get("active"))||!r.node(row.get("roles")).path("CUSTOMER").asBoolean())throw problem("INVALID_CUSTOMER","Chọn khách hàng đang hoạt động");}
 public Object options(Authentication a){if(!r.granular(a,"leads","VIEW")&&!r.granular(a,"opportunities","VIEW"))r.gate(a,"leads","VIEW");var branches=r.db.queryForList("select b.id,b.name,b.code from retail.branch b where b.tenant_id=? and b.active and "+(r.all(a)?"true":"exists(select 1 from retail.access_scope acl where acl.tenant_id=b.tenant_id and acl.branch_id=b.id and acl.account_id='"+r.actor(a)+"'::uuid)")+" order by b.is_default desc,b.name",r.tenant(a));var users=r.db.queryForList("select id,display_name from identity.account where tenant_id=? and enabled order by display_name",r.tenant(a));var customers=r.granular(a,"customer","VIEW")?r.db.queryForList("select id,code,name from retail.partner where tenant_id=? and active and roles->>'CUSTOMER'='true' order by name",r.tenant(a)):List.of();var leads=r.granular(a,"leads","VIEW")?r.db.queryForList("select l.id,l.code,l.name,l.branch_id,l.partner_id from retail.crm_lead l where l.tenant_id=? and "+r.branchScope(a,"l")+" and l.status<>'DISQUALIFIED' order by l.created_at desc limit 500",r.tenant(a)):List.of();return Map.of("branches",branches,"owners",users,"customers",customers,"leads",leads,"capabilities",new RetailPermissions(r).capabilities(a));}
 public Object list(Authentication a,boolean opp,String q,String state,int page){r.gate(a,feature(opp),"VIEW");if(page<0||page>100000||q.length()>160)throw problem("INVALID_FILTER","Bộ lọc không hợp lệ");String col=opp?"stage":"status";String where=" where x.tenant_id=? and "+r.branchScope(a,"x")+" and (x.name ilike ? or x.code ilike ?) and (?='' or x."+col+"=?)";String query="%"+q.trim()+"%";var count=r.db.queryForObject("select count(*) from retail."+table(opp)+" x"+where,Long.class,r.tenant(a),query,query,state,state);String join=opp?" left join retail.partner p on p.tenant_id=x.tenant_id and p.id=x.partner_id left join retail.crm_lead l on l.tenant_id=x.tenant_id and l.id=x.lead_id":"";String extras=opp?",p.name customer_name,l.name lead_name":"";var items=r.db.queryForList("select x.*,b.name branch_name,u.display_name owner_name"+extras+" from retail."+table(opp)+" x join retail.branch b on b.tenant_id=x.tenant_id and b.id=x.branch_id join identity.account u on u.tenant_id=x.tenant_id and u.id=x.owner_id"+join+where+" order by x.created_at desc,x.id limit 20 offset ?",r.tenant(a),query,query,state,state,page*20);return Map.of("items",items,"total",count,"page",page,"pageSize",20);}
 public Object save(Authentication a,boolean opp,UUID id,JsonNode x){r.gate(a,feature(opp),id==null?"CREATE":"UPDATE");var old=id==null?null:scoped(a,opp,id);if(old!=null){version(old,x);if(!opp&&"CONVERTED".equals(old.get("status")))throw problem("LEAD_CONVERTED","Tiềm năng đã chuyển đổi; cập nhật tại Customer Master");}UUID branch=branch(a,x),owner=owner(a,x),target=id==null?UUID.randomUUID():id;if(!opp&&old!=null&&!branch.equals(old.get("branch_id"))&&r.db.queryForObject("select count(*) from retail.crm_opportunity where tenant_id=? and lead_id=?",Integer.class,r.tenant(a),id)>0)throw problem("LEAD_BRANCH_IN_USE","Tiềm năng đã có cơ hội; không đổi địa điểm");String code=id==null?text(x,"code",""):old.get("code").toString();if(code.isBlank())code=(opp?"CH-":"TN-")+target.toString().substring(0,8).toUpperCase(Locale.ROOT);if(code.length()>60)throw problem("INVALID_CODE","Mã tối đa 60 ký tự");if(r.db.queryForObject("select count(*) from retail."+table(opp)+" where tenant_id=? and code=? and id<>?",Integer.class,r.tenant(a),code,target)>0)throw problem("DUPLICATE_CODE","Mã đã tồn tại",HttpStatus.CONFLICT);String name=required(x,"name",160),note=bounded(x,"note",4000);
 if(!opp){String status=text(x,"status","NEW"),email=bounded(x,"email",160);if(!Set.of("NEW","CONTACTED","QUALIFIED","DISQUALIFIED").contains(status))throw problem("INVALID_STATUS","Trạng thái tiềm năng không hợp lệ");if(!email.isBlank()&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw problem("INVALID_EMAIL","Email không hợp lệ");String company=bounded(x,"company",160),phone=bounded(x,"phone",60),address=bounded(x,"address",2000),source=bounded(x,"source",100);if(id==null)r.db.update("insert into retail.crm_lead(id,tenant_id,branch_id,code,name,company,phone,email,address,source,owner_id,status,note) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",target,r.tenant(a),branch,code,name,company,phone,email,address,source,owner,status,note);else r.db.update("update retail.crm_lead set branch_id=?,name=?,company=?,phone=?,email=?,address=?,source=?,owner_id=?,status=?,note=?,version=version+1,updated_at=now() where tenant_id=? and id=?",branch,name,company,phone,email,address,source,owner,status,note,r.tenant(a),id);
 }else{UUID lead=optional(x,"leadId"),partner=optional(x,"partnerId");if(lead==null&&partner==null)throw problem("CUSTOMER_REQUIRED","Chọn tiềm năng hoặc khách hàng");if(lead!=null){r.gate(a,"leads","VIEW");var l=scoped(a,false,lead);if(!branch.equals(l.get("branch_id")))throw problem("LEAD_BRANCH","Cơ hội phải cùng địa điểm với tiềm năng");if("DISQUALIFIED".equals(l.get("status")))throw problem("INVALID_LEAD","Tiềm năng không phù hợp");if(l.get("partner_id")!=null){if(partner!=null&&!partner.equals(l.get("partner_id")))throw problem("CUSTOMER_MISMATCH","Khách hàng khác tiềm năng đã chuyển đổi");partner=(UUID)l.get("partner_id");}}
 if(partner!=null)customer(a,partner);String stage=text(x,"stage","NEW"),reason=bounded(x,"lostReason",1000);if(!Set.of("NEW","CONTACTED","QUOTED","NEGOTIATION","WON","LOST").contains(stage))throw problem("INVALID_STAGE","Giai đoạn không hợp lệ");if(stage.equals("LOST")&&reason.isBlank())throw problem("LOST_REASON_REQUIRED","Nhập lý do không thành công");BigDecimal amount=num(x,"amount",BigDecimal.ZERO);if(amount.signum()<0||amount.stripTrailingZeros().scale()>0)throw problem("INVALID_AMOUNT","Giá trị dự kiến phải là số nguyên VND không âm");LocalDate close=text(x,"expectedClose","").isBlank()?null:date(x,"expectedClose");if(id==null)r.db.update("insert into retail.crm_opportunity(id,tenant_id,branch_id,code,name,lead_id,partner_id,owner_id,amount,expected_close,stage,lost_reason,note) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",target,r.tenant(a),branch,code,name,lead,partner,owner,amount,close,stage,reason,note);else r.db.update("update retail.crm_opportunity set branch_id=?,name=?,lead_id=?,partner_id=?,owner_id=?,amount=?,expected_close=?,stage=?,lost_reason=?,note=?,version=version+1,updated_at=now() where tenant_id=? and id=?",branch,name,lead,partner,owner,amount,close,stage,reason,note,r.tenant(a),id);}
 return r.one(table(opp),r.tenant(a),target);}
 @SuppressWarnings("unchecked") public Object convert(Authentication a,UUID id,JsonNode x){r.gate(a,"leads","CONVERT");var lead=scoped(a,false,id);version(lead,x);if("CONVERTED".equals(lead.get("status")))throw problem("LEAD_CONVERTED","Tiềm năng đã chuyển đổi",HttpStatus.CONFLICT);if("DISQUALIFIED".equals(lead.get("status")))throw problem("INVALID_LEAD","Tiềm năng không phù hợp chưa thể chuyển đổi");UUID partner=optional(x,"partnerId");if(partner!=null)customer(a,partner);else{r.gate(a,"customer","CREATE");var body=r.json.createObjectNode();body.put("code","KH-"+id.toString().substring(0,8).toUpperCase(Locale.ROOT));for(String key:List.of("name","phone","email","address"))body.put(key,Objects.toString(lead.get(key),""));body.put("entityType","PERSON");var created=(Map<String,Object>)partners.quickCustomer(a,body);partner=UUID.fromString(created.get("id").toString());}r.db.update("update retail.crm_lead set status='CONVERTED',partner_id=?,version=version+1,updated_at=now() where tenant_id=? and id=?",partner,r.tenant(a),id);r.db.update("update retail.crm_opportunity set partner_id=?,version=version+1,updated_at=now() where tenant_id=? and lead_id=? and partner_id is null",partner,r.tenant(a),id);return Map.of("partnerId",partner,"leadId",id);}
}
